    {
      "type": 1,
      "content": {
        "json": "# Azure VM previous-generation capacity readiness\r\n\r\nInventory, growth-risk and migration planning for VM series affected by July 2026\r\ncapacity limitations."
      },
      "name": "title"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "crossComponentResources": [
          "{Subscriptions}"
        ],
        "parameters": [
          {
            "id": "p-subs",
            "version": "KqlParameterItem/1.0",
            "name": "Subscriptions",
            "label": "Subscriptions",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "isRequired": true,
            "query": "resourcecontainers\n| where type =~ 'microsoft.resources/subscriptions'\n| where properties.state =~ 'Enabled'\n| project value = id, label = name, selected = true\n| order by label asc",
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "value::all"
            ],
            "typeSettings": {
              "additionalResourceOptions": [
                "value::all"
              ],
              "showDefault": false
            },
            "timeContext": {
              "durationMs": 86400000
            },
            "value": [
              "value::all"
            ],
            "description": "Subscriptions to scan for previous-generation VM exposure."
          },
          {
            "id": "p-rg",
            "version": "KqlParameterItem/1.0",
            "name": "ResourceGroups",
            "label": "Resource groups",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "query": "resources\n| where type =~ 'microsoft.compute/virtualmachines'\n    or type =~ 'microsoft.compute/virtualmachinescalesets'\n| summarize Resources = count() by resourceGroup\n| project value = resourceGroup, label = strcat(resourceGroup, ' (', Resources, ')'), selected = false\n| order by label asc",
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "{Subscriptions}"
            ],
            "typeSettings": {
              "additionalResourceOptions": [
                "value::all"
              ],
              "selectAllValue": "*",
              "showDefault": false
            },
            "timeContext": {
              "durationMs": 86400000
            },
            "value": [
              "value::all"
            ],
            "description": "Limit results to selected resource groups."
          },
          {
            "id": "p-regions",
            "version": "KqlParameterItem/1.0",
            "name": "Regions",
            "label": "Regions",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "query": "resources\n| where type =~ 'microsoft.compute/virtualmachines'\n    or type =~ 'microsoft.compute/virtualmachinescalesets'\n| summarize Resources = count() by location\n| project value = location, label = strcat(location, ' (', Resources, ')'), selected = false\n| order by label asc",
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "{Subscriptions}"
            ],
            "typeSettings": {
              "additionalResourceOptions": [
                "value::all"
              ],
              "selectAllValue": "*",
              "showDefault": false
            },
            "timeContext": {
              "durationMs": 86400000
            },
            "value": [
              "value::all"
            ],
            "description": "Limit results to selected Azure regions."
          },
          {
            "id": "p-inventory-query",
            "version": "KqlParameterItem/1.0",
            "name": "ComputeInventoryQuery",
            "type": 1,
            "value": "resources\r\n| where type =~ 'microsoft.compute/virtualmachines'\r\n    or type =~ 'microsoft.compute/virtualmachinescalesets'\r\n| extend\r\n    ResourceKind = iff(type =~ 'microsoft.compute/virtualmachines', 'VM', 'VMSS'),\r\n    TargetId = tolower(id),\r\n    VmSize = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.hardwareProfile.vmSize), tostring(sku.name)),\r\n    CurrentCapacity = iff(type =~ 'microsoft.compute/virtualmachines', 1, coalesce(toint(sku.capacity), 0)),\r\n    OperatingSystem = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.storageProfile.osDisk.osType), ''),\r\n    Priority = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.priority), ''),\r\n    AvailabilitySet = iff(type =~ 'microsoft.compute/virtualmachines', extract('/availabilitySets/([^/]+)$', 1, tostring(properties.availabilitySet.id)), ''),\r\n    EphemeralOS = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.storageProfile.osDisk.diffDiskSettings.option) =~ 'Local', false),\r\n    OrchestrationMode = tostring(properties.orchestrationMode),\r\n    UpgradeMode = tostring(properties.upgradePolicy.mode),\r\n    Zones = strcat_array(zones, ', ')\r\n| extend _sizeKey = toupper(VmSize)\r\n| extend Series = case(\r\n    _sizeKey matches regex '^STANDARD_F[0-9]+S_V2$', 'Fsv2',\r\n    _sizeKey matches regex '^STANDARD_FS[0-9]+_V2$', 'Fsv2',\r\n    _sizeKey matches regex '^STANDARD_FS[0-9]+$', 'Fs',\r\n    _sizeKey matches regex '^STANDARD_F[0-9]+[A-Z]*S$', 'Fs',\r\n    _sizeKey matches regex '^STANDARD_F[0-9]+$', 'F',\r\n\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?DS_V4$', 'Ddsv4',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?D_V4$', 'Ddv4',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+AS_V4$', 'Dasv4',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+A_V4$', 'Dav4',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V4$', 'Dsv4',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V4$', 'Dv4',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V3$', 'Dsv3',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V3$', 'Dv3',\r\n    _sizeKey matches regex '^STANDARD_DS[0-9]+_V2$', 'Dsv2',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V2$', 'Dsv2',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V2$', 'Dv2',\r\n    _sizeKey matches regex '^STANDARD_DS[0-9]+$', 'Ds',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+S$', 'Ds',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+$', 'D',\r\n\r\n    _sizeKey matches regex '^STANDARD_B[0-9]+[A-Z]*S$', 'Bs',\r\n    _sizeKey matches regex '^STANDARD_B[0-9]+[A-Z]*$', 'B',\r\n    _sizeKey matches regex '^STANDARD_A[0-9]+M_V2$', 'Amv2',\r\n    _sizeKey matches regex '^STANDARD_A[0-9]+_V2$', 'Av2',\r\n\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?DS_V4$', 'Edsv4',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?D_V4$', 'Edv4',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+AS_V4$', 'Easv4',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+A_V4$', 'Eav4',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?S_V4$', 'Esv4',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?_V4$', 'Ev4',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?S_V3$', 'Esv3',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?_V3$', 'Ev3',\r\n\r\n    _sizeKey matches regex '^STANDARD_GS[0-9]+$', 'Gs',\r\n    _sizeKey matches regex '^STANDARD_G[0-9]+S$', 'Gs',\r\n    _sizeKey matches regex '^STANDARD_G[0-9]+$', 'G',\r\n    _sizeKey matches regex '^STANDARD_L[0-9]+S_V2$', 'Lsv2',\r\n    _sizeKey matches regex '^STANDARD_L[0-9]+S$', 'Ls',\r\n    '')\r\n| extend Category = case(\r\n    Series in ('F','Fs','Fsv2'), 'Compute optimized',\r\n    Series in ('D','Ds','Dv2','Dsv2','Dv3','Dsv3','Dv4','Dsv4','Ddv4','Ddsv4','Dav4','Dasv4','B','Bs','Av2','Amv2'), 'General purpose',\r\n    Series in ('Ev3','Esv3','Ev4','Esv4','Edv4','Edsv4','Eav4','Easv4','G','Gs'), 'Memory optimized',\r\n    Series in ('Ls','Lsv2'), 'Storage optimized',\r\n    '')\r\n| extend RetirementDate = case(\r\n    Series in ('D','Ds','Dv2','Dsv2','Ls'), datetime(2028-05-01),\r\n    Series in ('Av2','Amv2','B','Bs','F','Fs','Fsv2','G','Gs','Lsv2'), datetime(2028-11-15),\r\n    todatetime(''))\r\n| extend LifecycleStatus = case(\r\n    isnotnull(RetirementDate), 'Capacity restricted + retirement scheduled',\r\n    isnotempty(Series), 'Capacity restricted; product active',\r\n    'Current generation')\r\n| extend RecommendedTarget = case(\r\n    Series in ('D','Ds','Dv2','Dsv2','Dv3','Dsv3','Dv4','Dsv4','Ddv4','Ddsv4','Dav4','Dasv4'), 'Dv5/Dsv5, Dv6/Dsv6, or Dv7/Dsv7',\r\n    Series in ('Ev3','Esv3','Ev4','Esv4','Edv4','Edsv4','Eav4','Easv4'), 'Ev5/Esv5, Esv6, or Esv7',\r\n    Series in ('Av2','Amv2'), 'Bsv2/Basv2 or D/E v5-v6',\r\n    Series in ('B','Bs'), 'Bsv2/Basv2 or Dlsv5-v6',\r\n    Series in ('F','Fs','Fsv2'), 'Dlsv5-v6, Dsv5, or Falsv6',\r\n    Series in ('G','Gs'), 'Lsv3/Lasv3 or Lsv4/Lasv4',\r\n    Series in ('Ls','Lsv2'), 'Lsv3/Lasv3 or Lsv4/Lasv4',\r\n    '')\r\n| project-away _sizeKey\r\n| where isnotempty(Series)\r\n| join kind=leftouter (\r\n    resources\r\n    | where type =~ 'microsoft.insights/autoscalesettings'\r\n    | mv-expand Profile = properties.profiles\r\n    | extend\r\n        TargetId = tolower(tostring(properties.targetResourceUri)),\r\n        ProfileMin = toint(Profile.capacity.minimum),\r\n        ProfileMax = toint(Profile.capacity.maximum)\r\n    | summarize AutoscaleMin = min(ProfileMin), AutoscaleMax = max(ProfileMax), AutoscaleProfiles = count() by TargetId\r\n  ) on TargetId\r\n| extend\r\n    AutoscaleMin = iff(ResourceKind == 'VM', 1, coalesce(AutoscaleMin, CurrentCapacity)),\r\n    AutoscaleMax = iff(ResourceKind == 'VM', 1, coalesce(AutoscaleMax, CurrentCapacity))\r\n| extend GrowthGap = iff(AutoscaleMax > CurrentCapacity, AutoscaleMax - CurrentCapacity, 0)\r\n| join kind=leftouter (\r\n    resourcecontainers\r\n    | where type =~ 'microsoft.resources/subscriptions'\r\n    | project subscriptionId, Subscription = name\r\n  ) on subscriptionId\r\n| extend\r\n    InstanceCount = CurrentCapacity,\r\n    Risk = case(ResourceKind == 'VMSS' and GrowthGap > 0, 'Critical', isnotnull(RetirementDate), 'High', 'Medium'),\r\n    RiskReason = case(\r\n        ResourceKind == 'VMSS' and GrowthGap > 0, 'Autoscale or planned growth uses a capacity-restricted series',\r\n        isnotnull(RetirementDate), 'Retirement scheduled and capacity growth restricted',\r\n        'Capacity growth restricted'),\r\n    MigrationConsiderations = strcat_array(array_concat(\r\n        iff(ResourceKind == 'VM' and isnotempty(AvailabilitySet), pack_array('Coordinate availability-set migration'), dynamic([])),\r\n        iff(ResourceKind == 'VM' and isnotempty(Zones), pack_array('Validate target size in current zone'), dynamic([])),\r\n        iff(ResourceKind == 'VM' and EphemeralOS, pack_array('Ephemeral OS disk - plan redeployment'), dynamic([])),\r\n        iff(ResourceKind == 'VM' and Priority =~ 'Spot', pack_array('Spot workload - validate replacement capacity'), dynamic([])),\r\n        iff(ResourceKind == 'VMSS' and GrowthGap > 0, pack_array(strcat('Autoscale growth gap: ', tostring(GrowthGap))), dynamic([])),\r\n        iff(ResourceKind == 'VMSS' and isnotempty(Zones), pack_array('Validate target size in every configured zone'), dynamic([])),\r\n        iff(ResourceKind == 'VMSS' and OrchestrationMode =~ 'Uniform', pack_array('Coordinate model and instance upgrade'), dynamic([]))\r\n      ), ' | '),\r\n    RiskRank = case(ResourceKind == 'VMSS' and GrowthGap > 0, 0, isnotnull(RetirementDate), 1, 2),\r\n    Resource = name,\r\n    Location = location,\r\n    ResourceId = id,\r\n    ResourceGroup = resourceGroup,\r\n    SubscriptionId = subscriptionId",
            "isHiddenWhenLocked": true,
            "typeSettings": {
              "multiLineText": true,
              "editorLanguage": "text"
            },
            "description": "Shared VM and VMSS inventory query used by workbook visualizations."
          }
        ],
        "style": "pills",
        "queryType": 1,
        "resourceType": "microsoft.resourcegraph/resources"
      },
      "name": "parameters"
    },
