    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "items": [
          {
            "type": 1,
            "content": {
              "json": "## Previous-generation VM capacity readiness\r\n\r\nStarting in July 2026, Azure applies capacity limitations to specific\r\nprevious-generation VM series. Existing running VMs continue to operate; the risk is\r\nfuture quota growth, new deployments, and scale-out on hardware with limited capacity.\r\n\r\nThis workbook uses Microsoft's explicit affected-series list. It does **not** assume\r\nthat every VM whose name contains `v1` through `v4` is affected.",
              "style": "warning"
            },
            "name": "ovHeader"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| summarize\n    AffectedInstances = sum(InstanceCount),\n    StandaloneVMs = countif(ResourceKind == 'VM'),\n    ScaleSets = countif(ResourceKind == 'VMSS'),\n    GrowthAtRisk = sum(GrowthGap),\n    RetirementScheduled = sumif(InstanceCount, isnotnull(RetirementDate)),\n    AffectedSubscriptions = dcount(SubscriptionId),\n    Regions = dcount(Location)\n| extend MetricRows = pack_array(\n    strcat('1|Affected VM instances|', tostring(AffectedInstances)),\n    strcat('2|Standalone VMs|', tostring(StandaloneVMs)),\n    strcat('3|VM scale sets|', tostring(ScaleSets)),\n    strcat('4|Autoscale growth at risk|', tostring(GrowthAtRisk)),\n    strcat('5|Retirement-scheduled instances|', tostring(RetirementScheduled)),\n    strcat('6|Affected subscriptions|', tostring(AffectedSubscriptions)),\n    strcat('7|Affected regions|', tostring(Regions))\n  )\n| mv-expand MetricRow = MetricRows to typeof(string)\n| extend MetricParts = split(MetricRow, '|')\n| project\n    Rank = toint(MetricParts[0]),\n    Metric = tostring(MetricParts[1]),\n    Value = tolong(MetricParts[2])\n| order by Rank asc",
              "size": 3,
              "title": "Capacity exposure summary",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "tiles",
              "tileSettings": {
                "titleContent": {
                  "columnMatch": "Metric",
                  "formatter": 1
                },
                "leftContent": {
                  "columnMatch": "Value",
                  "formatter": 12,
                  "formatOptions": {
                    "palette": "auto"
                  },
                  "numberFormat": {
                    "unit": 17,
                    "options": {
                      "style": "decimal",
                      "maximumFractionDigits": 0
                    }
                  }
                },
                "showBorder": true,
                "sortCriteriaField": "Rank",
                "sortOrderField": 1
              }
            },
            "name": "Capacityexposuresummary"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| summarize Instances = sum(InstanceCount) by Series\n| order by Instances desc",
              "size": 1,
              "title": "Affected instances by series",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "barchart"
            },
            "name": "Affectedinstancesbyseries"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| summarize Instances = sum(InstanceCount) by Region = Location\n| order by Instances desc",
              "size": 1,
              "title": "Affected instances by region",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "barchart"
            },
            "name": "Affectedinstancesbyregion"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| summarize Resources = count() by Risk\n| extend RiskRank = case(Risk == 'Critical', 0, Risk == 'High', 1, Risk == 'Medium', 2, 3)\n| order by RiskRank asc\n| project-away RiskRank",
              "size": 1,
              "title": "Resources by risk",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "piechart"
            },
            "name": "Resourcesbyrisk"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| project\n    Resource,\n    Risk,\n    ['Capacity / lifecycle'] = LifecycleStatus,\n    Type = ResourceKind,\n    Subscription,\n    ['Resource group'] = ResourceGroup,\n    Region = Location,\n    ['VM size'] = VmSize,\n    Series,\n    ['Instances'] = InstanceCount,\n    ['Growth at risk'] = GrowthGap,\n    ['Retirement date'] = RetirementDate,\n    ['Target family guidance'] = RecommendedTarget,\n    ResourceId,\n    RiskRank\n| order by ['Instances'] desc, RiskRank asc, ['Growth at risk'] desc, Resource asc\n| project-away RiskRank",
              "size": 2,
              "title": "All impacted VMs and scale sets",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "showExportToExcel": true,
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true,
                "formatters": [
                  {
                    "columnMatch": "Risk",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "colors",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "Critical",
                          "representation": "redBright",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "==",
                          "thresholdValue": "High",
                          "representation": "red",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "==",
                          "thresholdValue": "Medium",
                          "representation": "orange",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "Default",
                          "representation": "gray",
                          "text": "{0}{1}"
                        }
                      ]
                    }
                  },
                  {
                    "columnMatch": "Capacity / lifecycle",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "colors",
                      "thresholdsGrid": [
                        {
                          "operator": "contains",
                          "thresholdValue": "retirement scheduled",
                          "representation": "red",
