                        },
                        {
                          "operator": "contains",
                          "thresholdValue": "product active",
                          "representation": "orange",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "Default",
                          "representation": "gray",
                          "text": "{0}{1}"
                        }
                      ]
                    }
                  },
                  {
                    "columnMatch": "Growth at risk",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "colors",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "0",
                          "representation": "green",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": ">",
                          "thresholdValue": "0",
                          "representation": "redBright",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "Default",
                          "representation": "gray",
                          "text": "{0}{1}"
                        }
                      ]
                    },
                    "numberFormat": {
                      "unit": 0,
                      "options": {
                        "style": "decimal",
                        "maximumFractionDigits": 0
                      },
                      "emptyValCustomText": "0"
                    }
                  },
                  {
                    "columnMatch": "Retirement date",
                    "formatter": 6,
                    "formatOptions": {
                      "customColumnWidthSetting": "18ch"
                    },
                    "dateFormat": {
                      "showUtcTime": true,
                      "formatName": "shortDatePattern"
                    }
                  },
                  {
                    "columnMatch": "ResourceId",
                    "formatter": 13,
                    "formatOptions": {
                      "linkColumn": "ResourceId",
                      "linkTarget": "Resource",
                      "linkIsContextBlade": true,
                      "showIcon": true,
                      "customColumnWidthSetting": "32ch"
                    }
                  }
                ],
                "sortBy": [
                  {
                    "itemKey": "Instances",
                    "sortOrder": 2
                  }
                ]
              }
            },
            "name": "AllimpactedVMsandscalesets"
          }
        ]
      },
      "conditionalVisibility": {
        "parameterName": "selectedTab",
        "comparison": "isEqualTo",
        "value": "overview"
      },
      "name": "group-overview"
    },
    {
