            "content": {
              "version": "KqlItem/1.0",
              "query": "advisorresources\n| where type =~ 'microsoft.advisor/recommendations'\n| where iff(strlen(name) == 36, properties.lastUpdated > ago(1d), properties.platformState == 'New')\n| where isempty(properties.tracked)\n| extend\n    ResourceId = tolower(tostring(properties.resourceMetadata.resourceId)),\n    ServiceID = tostring(properties.recommendationTypeId),\n    RecommendationState = tostring(properties.platformState)\n| where isnotempty(ResourceId)\n    and isnotempty(ServiceID)\n    and ServiceID == '{SelectedVmRetirementServiceId}'\n| join kind=inner (\n    resources\n    | where type =~ 'microsoft.compute/virtualmachines'\n        or type =~ 'microsoft.compute/virtualmachinescalesets'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n    | join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n    | extend\n        ResourceId = tolower(id),\n        ResourceKind = iff(type =~ 'microsoft.compute/virtualmachines', 'VM', 'VMSS'),\n        VmSize = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.hardwareProfile.vmSize), tostring(sku.name)),\n        Capacity = iff(type =~ 'microsoft.compute/virtualmachines', 1, coalesce(toint(sku.capacity), 0))\n    | project\n        ResourceId,\n        Resource = name,\n        Type = ResourceKind,\n        ['Current size'] = VmSize,\n        Capacity,\n        Subscription,\n        ['Resource group'] = resourceGroup,\n        Region = location,\n        Tags = tostring(tags)\n  ) on ResourceId\n| project\n    Resource,\n    Subscription,\n    ['Resource group'],\n    Type,\n    ['Current size'],\n    Capacity,\n    Region,\n    ['Recommendation state'] = RecommendationState,\n    ResourceId,\n    Tags\n| distinct Resource, Subscription, ['Resource group'], Type, ['Current size'], Capacity, Region, ['Recommendation state'], ResourceId, Tags\n| order by Capacity desc, Resource asc",
              "size": 3,
